  INSERT INTO _n5_mnemonics_212 (character, mnemonic) VALUES
    ('先', '<p><strong>Petunjuk bentuk:</strong> Bagian atas memiliki dua palang, satu batang tegak, dan goresan miring pendek di kiri atas. Dua goresan di bawah membuka seperti kaki yang melangkah lebih dahulu.</p>'),
    ('生', '<p><strong>Petunjuk bentuk:</strong> Garis bawah seperti tanah, batang tegak menjulang di tengah, dan garis-garis atas seperti daun tanaman yang hidup.</p>'),
    ('学', '<p><strong>Penyusun:</strong> ⺍ (tiga goresan kecil, paling atas) + 冖 (penutup datar, tengah) + 子 (anak, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan anak 子 belajar di bawah penutup 冖, dengan tiga percikan ide ⺍ di atasnya.</p>'),
    ('校', '<p><strong>Penyusun:</strong> 木 (pohon, kiri) + 交 (bersilang, unsur bunyi di kanan)</p><p>交 berperan sebagai unsur bunyi pada 校.</p>'),
    ('国', '<p><strong>Penyusun:</strong> 囗 (bingkai yang mengelilingi) + 玉 (permata, di dalam)</p><p>Ini pembagian visual bentuk 国 modern, bukan penjelasan asal-usulnya.</p><p><strong>Petunjuk bentuk:</strong> Bingkai 囗 mengelilingi seluruh 玉. Perhatikan titik kecil pada 玉 agar tidak tertukar dengan 王.</p><p><strong>Cara ingat:</strong> Bayangkan negara berbentuk tembok 囗 yang mengelilingi batu permata 玉 untuk melindunginya.</p>'),
    ('名', '<p><strong>Penyusun:</strong> 夕 (senja, atas) + 口 (mulut, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan mulut 口 menyebutkan nama saat senja 夕, ketika wajah mulai sulit terlihat.</p>'),
    ('人', '<p><strong>Petunjuk bentuk:</strong> Dua goresan bertemu di atas lalu membuka ke bawah, seperti orang yang berdiri dengan kedua kaki terbuka.</p>'),
    ('語', '<p><strong>Penyusun:</strong> 言 (kata atau berkata, kiri) + 吾 (unsur bunyi, kanan)</p><p>言 berkaitan dengan kata dan bahasa. 吾 berperan sebagai unsur bunyi yang memberi petunjuk bacaan ゴ.</p><p><strong>Petunjuk bentuk:</strong> Bentuk 吾 di kanan terdiri dari 五 di atas dan 口 di bawah.</p>'),
    ('何', '<p><strong>Penyusun:</strong> 亻 (orang, kiri) + 可 (unsur bunyi, kanan)</p><p>可 menjadi unsur bunyi untuk bacaan on&#39;yomi カ.</p><p><strong>Petunjuk bentuk:</strong> Pada 可, kotak 口 berada di bawah garis mendatar dengan kait panjang di kanan.</p>'),
    ('魚', '<p><strong>Penyusun:</strong> ⺈ (bentuk kepala berkait, atas) + 田 (kotak berpetak, tengah) + 灬 (empat titik, bawah)</p><p>Bagian-bagian ini dipakai sebagai petunjuk bentuk modern.</p><p><strong>Cara ingat:</strong> Bayangkan ikan tegak dengan kepala berkait, tubuh berpetak, dan empat sirip pendek berjajar di bawah.</p>'),
    ('本', '<p><strong>Penyusun:</strong> 木 (pohon, bentuk utama) + 一 (garis pendek di pangkal batang)</p><p><strong>Petunjuk bentuk:</strong> Garis pendek tambahan melintasi bagian bawah batang 木.</p><p><strong>Cara ingat:</strong> Bayangkan pangkal pohon 木 ditandai garis pendek. Kayu dari pohon itu dijadikan kertas untuk membuat buku.</p>'),
    ('花', '<p><strong>Penyusun:</strong> 艹 (rumput, atas) + 化 (berubah, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan rumput 艹 di atas berubah 化 menjadi bunga saat disiram.</p>'),
    ('一', '<p><strong>Petunjuk bentuk:</strong> Satu garis mendatar.</p>'),
    ('二', '<p><strong>Petunjuk bentuk:</strong> Dua garis mendatar. Garis bawah lebih panjang.</p>'),
    ('三', '<p><strong>Petunjuk bentuk:</strong> Tiga garis mendatar. Garis tengah paling pendek dan garis bawah paling panjang.</p>'),
    ('四', '<p><strong>Penyusun:</strong> 囗 (bingkai luar) + 儿 (dua goresan membuka, di dalam)</p><p><strong>Petunjuk bentuk:</strong> Bingkai memiliki empat sudut, dengan dua goresan terpisah di dalamnya.</p>'),
    ('五', '<p><strong>Petunjuk bentuk:</strong> Garis mendatar di atas dan bawah mengapit penyangga yang berbelok di tengah.</p>'),
    ('六', '<p><strong>Petunjuk bentuk:</strong> Satu titik di atas garis mendatar. Dua goresan bawah membuka ke kiri dan kanan.</p>'),
    ('七', '<p><strong>Petunjuk bentuk:</strong> Garis melintang menembus batang yang menekuk dan berkait ke kanan di bagian bawah.</p>'),
    ('八', '<p><strong>Petunjuk bentuk:</strong> Dua goresan miring terpisah yang semakin menjauh ke bawah.</p>'),
    ('九', '<p><strong>Petunjuk bentuk:</strong> Satu garis miring turun ke kiri. Garis lainnya membelok ke bawah, lalu berkait ke kanan.</p>'),
    ('十', '<p><strong>Petunjuk bentuk:</strong> Satu garis mendatar dan satu garis tegak bersilangan seperti tanda tambah.</p>'),
    ('安', '<p><strong>Penyusun:</strong> 宀 (atap, atas) + 女 (perempuan, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan perempuan 女 berteduh di bawah atap 宀 penginapan murah, lalu beristirahat dengan tenang.</p>'),
    ('高', '<p><strong>Petunjuk bentuk:</strong> Bentuknya seperti gedung tinggi: penutup kecil di puncak, kotak kecil di tengah atas, lalu bingkai besar dengan kotak di bagian bawah.</p>'),
    ('古', '<p><strong>Penyusun:</strong> 十 (sepuluh, atas) + 口 (mulut, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan peti berbentuk 口 dengan tanda silang 十 di atasnya. Peti itu berdebu dan sudah sangat tua.</p>'),
    ('新', '<p><strong>Penyusun:</strong> 立 (berdiri, kiri atas) + 木 (pohon, kiri bawah) + 斤 (kapak, kanan)</p><p>Ini pembagian visual bentuk modern. Bagian kiri secara keseluruhan berperan sebagai unsur bunyi.</p><p><strong>Cara ingat:</strong> Bayangkan kapak 斤 membentuk kayu 木 menjadi papan baru yang berdiri tegak seperti 立.</p>'),
    ('白', '<p><strong>Petunjuk bentuk:</strong> Kotak tegak seperti 日 dengan satu goresan pendek miring di kiri atas. Goresan tambahan itu membedakan 白 dari 日.</p>'),
    ('長', '<p><strong>Petunjuk bentuk:</strong> Bagian atas memiliki batang tegak dan deretan garis mendatar. Bagian bawah melebar, dengan ujung panjang yang menyapu ke kanan.</p>'),
    ('男', '<p><strong>Penyusun:</strong> 田 (sawah, atas) + 力 (tenaga, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan seorang laki-laki memakai tenaga 力 untuk bekerja di sawah 田.</p>'),
    ('女', '<p><strong>Petunjuk bentuk:</strong> Tiga goresan saling berpotongan: satu garis bertekuk, satu sapuan miring, dan satu garis mendatar yang melintas di tengah.</p>'),
    ('気', '<p><strong>Penyusun:</strong> 气 (uap atau napas, bagian luar) + dua goresan bersilang (bagian dalam)</p><p>Perhatikan bentuk 気 yang dipakai sekarang: bagian dalamnya berupa silang, bukan 米 seperti pada bentuk lama 氣.</p>'),
    ('上', '<p><strong>Petunjuk bentuk:</strong> Garis mendatar panjang menjadi dasar; garis tegak dan satu cabang pendek berada di atasnya.</p>'),
    ('下', '<p><strong>Petunjuk bentuk:</strong> Garis mendatar panjang berada di atas; garis tegak dan satu goresan pendek turun di bawahnya.</p>'),
    ('中', '<p><strong>Petunjuk bentuk:</strong> Sebuah kotak ditembus garis tegak tepat di tengah; garis itu memanjang melewati sisi atas dan bawah kotak.</p>'),
    ('外', '<p><strong>Penyusun:</strong> 夕 (petang, kiri) + 卜 (ramalan, kanan)</p><p>Perhatikan posisi: 夕 di kiri, 卜 di kanan. Cabang pendek 卜 berada di kanan garis tegaknya.</p>'),
    ('左', '<p><strong>Penyusun:</strong> 𠂇 (dua goresan berupa garis mendatar dan sapuan ke kiri, atas) + 工 (kerja atau kerajinan, bawah)</p><p>Bedakan pasangan ini dari 右: bagian bawah 左 adalah 工.</p>'),
    ('右', '<p><strong>Penyusun:</strong> 𠂇 (dua goresan berupa garis mendatar dan sapuan ke kiri, atas) + 口 (mulut, bawah)</p><p>Bedakan pasangan ini dari 左: bagian bawah 右 adalah 口.</p>'),
    ('前', '<p><strong>Penyusun:</strong> 䒑 (dua goresan pendek di atas garis mendatar, atas) + 月 (bentuk mirip bulan, kiri bawah) + 刂 (bentuk samping 刀, pisau, kanan bawah)</p><p>Bagian kiri bawah dipakai sebagai petunjuk bentuk yang menyerupai 月.</p>'),
    ('後', '<p><strong>Penyusun:</strong> 彳 (dua sapuan pendek dan satu garis tegak, kiri) + 幺 (bentuk kecil bertekuk, kanan atas) + 夂 (tiga goresan seperti kaki, kanan bawah)</p><p>Di kanan, kenali 幺 di atas dan 夂 di bawah.</p>'),
    ('間', '<p><strong>Penyusun:</strong> 門 (gerbang, luar) + 日 (matahari atau hari, dalam)</p><p><strong>Cara ingat:</strong> Bayangkan sinar matahari 日 masuk melalui sela di antara dua daun gerbang 門.</p>'),
    ('車', '<p><strong>Petunjuk bentuk:</strong> Perhatikan kotak berpetak di tengah, garis mendatar di atas dan bawahnya, serta garis tegak yang menembus semuanya.</p>'),
    ('東', '<p><strong>Penyusun:</strong> 木 (pohon, membentang dari atas ke bawah) + 日 (matahari, bertumpuk di tengah)</p><p>木 dan 日 saling bertumpuk dan berbagi garis. Pemecahan ini adalah bantuan visual untuk bentuk modern, bukan penjelasan asal-usul 東.</p><p><strong>Cara ingat:</strong> Bayangkan matahari 日 terlihat di tengah pohon 木 saat terbit dari timur.</p>'),
    ('西', '<p><strong>Petunjuk bentuk:</strong> Ada garis mendatar di atas kotak lebar. Di dalam kotak, satu goresan turun ke kiri dan satu goresan turun lalu bertekuk ke kanan.</p>'),
    ('南', '<p><strong>Penyusun:</strong> 十 (bentuk silang, atas) + 冂 (bingkai terbuka ke bawah, luar bawah) + dua goresan pendek di atas dua palang yang ditembus garis tegak (dalam)</p><p>Bagian dalam dijelaskan dari garis yang terlihat; tidak perlu memberinya nama kanji lain.</p>'),
    ('北', '<p><strong>Petunjuk bentuk:</strong> Dua bagian berdampingan: bagian kiri memiliki garis tegak dengan dua cabang ke kiri, sedangkan bagian kanan melengkung dan berkait ke kanan bawah.</p>'),
    ('道', '<p><strong>Penyusun:</strong> 辶 (bentuk jalan atau gerak, kiri dan bawah) + 首 (kepala, kanan atas)</p><p>辶 membentang sampai ke bawah 首; bentuknya bukan hanya goresan kecil di sisi kiri.</p><p><strong>Cara ingat:</strong> Bayangkan kepala 首 menghadap ke depan sambil mengikuti jalan 辶.</p>'),
    ('駅', '<p><strong>Penyusun:</strong> 馬 (kuda, kiri) + 尺 (satuan panjang, kanan)</p><p>馬 di kiri tampak lebih sempit daripada saat berdiri sendiri. 尺 di kanan membantu mengenali bentuk modern 駅.</p>'),
    ('行', '<p><strong>Penyusun:</strong> 彳 (dua sapuan pendek dan satu garis tegak, kiri) + 亍 (dua garis mendatar dan satu garis tegak berkait, kanan)</p><p>Ini pemisahan bentuk kiri dan kanan untuk latihan mengenali 行.</p>'),
    ('電', '<p><strong>Penyusun:</strong> 雨 (hujan, atas) + bentuk mirip 田 dengan garis tengah memanjang dan berkait (bawah)</p><p>Bagian bawah tidak sama persis dengan 田: perhatikan ekor berkait yang keluar ke kanan.</p>'),
    ('見', '<p><strong>Penyusun:</strong> 目 (mata, atas) + 儿 (bentuk dua kaki, bawah)</p><p><strong>Cara ingat:</strong> Bayangkan mata 目 yang mempunyai dua kaki 儿 dan mendekat agar bisa melihat lebih jelas.</p>'),
    ('読', '<p><strong>Penyusun:</strong> 言 (kata atau berkata, kiri) + 売 (menjual, kanan)</p><p>言 berkaitan dengan kata. 売 menjadi penanda bentuk bagian kanan pada kanji modern.</p><p><strong>Cara ingat:</strong> Bayangkan kata-kata 言 pada papan barang yang dijual 売; kamu membacanya sebelum membeli.</p>'),
    ('書', '<p><strong>Penyusun:</strong> 聿 (kuas, atas) + 曰 (kotak bergaris, bawah)</p><p>Bagian bawahnya adalah 曰, berbentuk kotak mendatar dengan garis di dalam.</p><p><strong>Cara ingat:</strong> Bayangkan kuas 聿 menulis pada bidang kotak bergaris di bawahnya.</p>'),
    ('年', '<p><strong>Petunjuk bentuk:</strong> Perhatikan goresan miring pendek di kiri atas, susunan garis mendatar, satu garis pendek di kiri tengah, dan garis tegak panjang yang turun melewati palang bawah.</p>'),
    ('百', '<p><strong>Penyusun:</strong> 一 (satu garis mendatar, atas) + 白 (putih, bawah)</p><p>白 berfungsi sebagai unsur bunyi. Kenali letaknya di bawah garis mendatar paling atas.</p>'),
    ('午', '<p><strong>Petunjuk bentuk:</strong> Dua palang mendatar ditembus garis tegak, dengan sapuan pendek di kiri atas. Garis tegaknya tidak melewati palang paling atas; ini membantu membedakannya dari 牛.</p>'),
    ('半', '<p><strong>Penyusun:</strong> 丷 (dua goresan pendek, atas) + 干 (dua garis mendatar ditembus garis tegak, bawah)</p><p>Perhatikan garis tegak di tengah yang membagi bentuk kiri dan kanan.</p>'),
    ('週', '<p><strong>Penyusun:</strong> 辶 (bentuk jalan atau gerak, kiri dan bawah) + 周 (keliling, kanan atas)</p><p>辶 berkaitan dengan gerak. 周 berperan dalam makna berkeliling sekaligus menjadi unsur bunyi untuk シュウ.</p><p><strong>Cara ingat:</strong> Bayangkan satu putaran 周 pada jadwal perjalanan 辶 yang berulang setiap pekan.</p>'),
    ('万', '<p><strong>Petunjuk bentuk:</strong> Tiga goresan: garis mendatar di atas, goresan bersudut dan berkait di kanan, serta sapuan panjang ke kiri bawah.</p>'),
    ('千', '<p><strong>Petunjuk bentuk:</strong> Bentuknya mirip 十 dengan satu sapuan pendek miring di bagian paling atas. Bedakan dari 午 yang memiliki dua palang mendatar.</p>'),
    ('毎', '<p><strong>Penyusun:</strong> 𠂉 (sapuan pendek dan garis mendatar, atas) + 毋 (bingkai dengan garis melintang, bawah)</p><p>Bagian bawah bentuk modern 毎 adalah 毋, bukan 母. Perhatikan garis di tengahnya, bukan dua titik seperti pada 母.</p>'),
    ('食', '<p><strong>Petunjuk bentuk:</strong> Bagian atas seperti tudung runcing. Di bawahnya ada wadah bertingkat dengan ujung bawah mencuat ke kanan.</p><p><strong>Cara ingat:</strong> Bayangkan tudung saji menutupi wadah berisi makanan yang siap kamu makan.</p>'),
    ('飲', '<p><strong>Penyusun:</strong> 飠 (bentuk 食, makanan, di kiri) + 欠 (orang membuka mulut, di kanan)</p><p><strong>Cara ingat:</strong> Bayangkan makanan 飠 di kiri dan orang membuka mulut 欠 di kanan. Setelah makan, ia minum air.</p>'),
    ('立', '<p><strong>Petunjuk bentuk:</strong> Titik di atas, garis mendatar di bawahnya, lalu dua garis miring yang berpijak pada garis dasar. Bayangkan orang berdiri di atas tanah.</p>'),
    ('休', '<p><strong>Penyusun:</strong> 亻 (bentuk 人, orang, di kiri) + 木 (pohon, di kanan)</p><p><strong>Cara ingat:</strong> Bayangkan orang 亻 bersandar pada pohon 木 untuk beristirahat.</p>'),
    ('入', '<p><strong>Petunjuk bentuk:</strong> Dua garis membuka ke bawah. Garis kanan mulai sedikit lebih tinggi daripada titik pertemuannya dengan garis kiri. Perhatikan puncaknya agar tidak tertukar dengan 人.</p><p><strong>Cara ingat:</strong> Bayangkan dua sisi pintu tenda yang kamu sibak untuk masuk.</p>'),
    ('出', '<p><strong>Petunjuk bentuk:</strong> Dua bingkai terbuka bertumpuk, dengan satu garis tegak menembus bagian tengah dan keluar di atas bingkai teratas.</p>'),
    ('言', '<p><strong>Penyusun:</strong> 口 (mulut, di bawah) + deretan garis di atasnya</p><p><strong>Cara ingat:</strong> Bayangkan kata-kata keluar dari mulut 口 dan menjadi garis-garis di atasnya.</p>'),
    ('話', '<p><strong>Penyusun:</strong> 言 (kata atau ucapan, di kiri) + 舌 (lidah, di kanan)</p><p><strong>Cara ingat:</strong> Bayangkan lidah 舌 bergerak untuk mengucapkan kata-kata 言 saat berbicara.</p>'),
    ('聞', '<p><strong>Penyusun:</strong> 門 (gerbang, bagian luar) + 耳 (telinga, di dalam)</p><p>耳 memberi petunjuk makna mendengar. 門 berfungsi sebagai unsur bunyi.</p><p><strong>Cara ingat:</strong> Bayangkan telinga 耳 mendengarkan percakapan dari balik gerbang 門.</p>'),
    ('買', '<p><strong>Penyusun:</strong> 罒 (bentuk jaring, di atas) + 貝 (kerang, di bawah)</p><p><strong>Cara ingat:</strong> Bayangkan jaring 罒 berisi kerang 貝 yang kamu bawa sebagai uang untuk membeli barang.</p>'),
    ('店', '<p><strong>Penyusun:</strong> 广 (atap bangunan, di luar) + 占 (bagian di bawah atap)</p><p>广 berkaitan dengan bangunan. 占 berfungsi sebagai unsur bunyi.</p>'),
    ('円', '<p><strong>Petunjuk bentuk:</strong> Bingkai luarnya terbuka di bawah. Di dalamnya ada satu garis mendatar dan satu garis tegak pendek dari atas.</p><p><strong>Cara ingat:</strong> Bayangkan bingkai 円 sebagai loket tempat menukar uang dengan koin yen yang bulat.</p>'),
    ('会', '<p><strong>Penyusun:</strong> 人 (bentuk orang, di atas) + 云 (bagian bawah)</p><p>Pembagian ini membantu mengenali bentuk 会 modern.</p><p><strong>Cara ingat:</strong> Bayangkan orang-orang bertemu dan berkumpul di bawah satu atap berbentuk 人.</p>'),
    ('社', '<p><strong>Penyusun:</strong> 礻 (bentuk 示, berkaitan dengan pemujaan, di kiri) + 土 (tanah, di kanan)</p><p>社 dipakai untuk tempat pemujaan dan kelompok atau organisasi, termasuk perusahaan dalam kata 会社.</p>'),
    ('日', '<p><strong>Petunjuk bentuk:</strong> Bingkai tegak dengan satu garis mendatar di dalamnya. Ingat matahari yang menandai pergantian hari.</p>'),
    ('月', '<p><strong>Petunjuk bentuk:</strong> Sisi kiri melengkung, sisi kanan tegak berkait, dan dua garis pendek di dalamnya. Bayangkan bulan sabit.</p>'),
    ('火', '<p><strong>Petunjuk bentuk:</strong> Dua garis panjang di tengah seperti nyala api. Dua garis pendek di kiri dan kanan seperti percikan api.</p>'),
    ('水', '<p><strong>Petunjuk bentuk:</strong> Garis panjang berkait di tengah, dengan cabang di kiri dan kanan. Bayangkan arus air yang memercik ke samping.</p>'),
    ('木', '<p><strong>Petunjuk bentuk:</strong> Satu garis tegak menjadi batang, garis mendatar menjadi cabang, dan dua garis miring membuka ke bawah seperti akar pohon.</p>'),
    ('金', '<p><strong>Petunjuk bentuk:</strong> Bagian atas seperti atap. Di bawahnya ada tiga garis mendatar, satu garis tegak di tengah, dan dua goresan kecil di kiri dan kanan.</p><p><strong>Cara ingat:</strong> Bayangkan dua goresan kecil sebagai butir emas dalam tambang bertingkat di bawah atap.</p>'),
    ('土', '<p><strong>Petunjuk bentuk:</strong> Satu garis tegak melewati dua garis mendatar. Garis bawah lebih panjang daripada garis atas, seperti permukaan tanah yang lebar.</p>'),
    ('時', '<p><strong>Penyusun:</strong> 日 (matahari atau hari, di kiri) + 寺 (bagian di kanan)</p><p>日 berkaitan dengan hari dan waktu. 寺 berfungsi sebagai unsur bunyi.</p>'),
    ('分', '<p><strong>Penyusun:</strong> 八 (dua sisi yang membuka, di atas) + 刀 (pisau, di bawah)</p><p><strong>Cara ingat:</strong> Bayangkan pisau 刀 membagi benda menjadi dua bagian yang membuka seperti 八.</p>'),
    ('子', '<p><strong>Petunjuk bentuk:</strong> Lengkungan di atas seperti kepala anak. Garis mendatar menjadi dua lengan, dan garis turun berkait menjadi tubuhnya.</p>'),
    ('父', '<p><strong>Petunjuk bentuk:</strong> Dua garis pendek di atas dan dua garis panjang bersilang di bawah. Bayangkan alis ayah di atas kedua lengannya yang bersilang.</p>'),
    ('母', '<p><strong>Petunjuk bentuk:</strong> Bingkai miring dengan satu garis melintang dan dua titik di dalam. Bayangkan sabuk dan dua kancing pada baju ibu.</p>'),
    ('友', '<p><strong>Penyusun:</strong> 𠂇 (bagian atas, seperti lengan terulur) + 又 (bagian bawah, seperti tangan)</p><p><strong>Cara ingat:</strong> Bayangkan dua tangan saling menyambut untuk bersalaman dengan teman.</p>'),
    ('手', '<p><strong>Petunjuk bentuk:</strong> Garis-garis melintang seperti jari yang terbuka. Garis panjang berkait menembus tengahnya, seperti pergelangan tangan.</p>'),
    ('足', '<p><strong>Penyusun:</strong> 口 (bentuk kotak, di atas) + bagian bawah seperti tungkai dan telapak</p><p><strong>Cara ingat:</strong> Bayangkan kotak atas sebagai lutut, lalu ikuti tungkai hingga telapak kaki yang mengarah ke kanan.</p>'),
    ('口', '<p><strong>Petunjuk bentuk:</strong> Kotak kosong tanpa garis di dalamnya, seperti mulut yang terbuka.</p>'),
    ('目', '<p><strong>Petunjuk bentuk:</strong> Bingkai tegak dengan dua garis mendatar di dalamnya, seperti mata yang diputar tegak. Perhatikan dua garisnya untuk membedakan 目 dari 日.</p>'),
    ('耳', '<p><strong>Petunjuk bentuk:</strong> Dua sisi tegak dihubungkan garis-garis mendatar. Garis bawah menonjol ke samping, seperti lipatan pada telinga.</p>'),
    ('大', '<p><strong>Penyusun:</strong> 人 (bentuk orang) + garis mendatar seperti lengan terbuka</p><p><strong>Cara ingat:</strong> Bayangkan orang 大 merentangkan tangan dan kaki lebar-lebar untuk menunjukkan ukuran besar.</p>'),
    ('小', '<p><strong>Petunjuk bentuk:</strong> Satu garis tegak berkait di tengah, diapit dua goresan pendek. Bayangkan tubuh kecil dengan dua tangan mungil.</p>'),
    ('多', '<p><strong>Penyusun:</strong> 夕 (bentuk yang muncul dua kali, atas dan bawah)</p><p>Gunakan pengulangan bentuk 夕 sebagai pengingat jumlah yang bertambah.</p><p><strong>Cara ingat:</strong> Bayangkan potongan berbentuk 夕 ditumpuk lagi dan lagi sampai jumlahnya banyak.</p>'),
    ('少', '<p><strong>Penyusun:</strong> Bentuk seperti 小 (kecil, di atas) + satu garis miring panjang di bawah</p><p><strong>Cara ingat:</strong> Bayangkan bentuk kecil di atas sebagai beberapa butir beras. Garis miring menjadi sendok yang hanya mengambil sedikit beras.</p>'),
    ('雨', '<p><strong>Petunjuk bentuk:</strong> Satu garis mendatar di atas bingkai, satu sekat tegak di tengah, dan empat titik di dalamnya. Bayangkan tetes hujan terlihat melalui jendela bersekat.</p>'),
    ('天', '<p><strong>Penyusun:</strong> 大 (bentuk orang) + satu garis mendatar di atasnya</p><p><strong>Cara ingat:</strong> Bayangkan orang 大 berdiri di bawah garis langit yang membentang di atas kepalanya.</p>'),
    ('空', '<p><strong>Penyusun:</strong> 穴 (lubang, di atas) + 工 (bagian di bawah)</p><p>穴 memberi petunjuk makna ruang kosong. 工 berfungsi sebagai unsur bunyi.</p>'),
    ('山', '<p><strong>Petunjuk bentuk:</strong> Tiga garis tegak terhubung di bawah. Garis tengah paling tinggi, seperti puncak gunung di antara dua puncak kecil.</p>'),
    ('川', '<p><strong>Petunjuk bentuk:</strong> Tiga garis panjang berdampingan, seperti arus sungai yang mengalir sejajar.</p>'),
    ('来', '<p><strong>Petunjuk bentuk:</strong> Satu garis tegak di tengah, dua garis mendatar, dua goresan pendek di kiri dan kanan, serta dua garis miring membuka ke bawah.</p><p><strong>Cara ingat:</strong> Bayangkan 来 sebagai pohon kecil dengan dua buah. Akarnya berubah menjadi kaki, lalu pohon itu datang menghampirimu.</p>'),
    ('令', '<p><strong>Petunjuk bentuk:</strong> Bagian atas seperti atap runcing. Di bawahnya ada titik dan bentuk bersudut yang menekuk.</p><p><strong>Cara ingat:</strong> Bayangkan seseorang di bawah atap menunduk untuk menerima perintah.</p>');
